integer nrow, ncol, i, j, dr, dc, nr, nc, cr, cc, top, sz
integer ndies, nring, ncl, lmax
integer g(256,256), vis(256,256), sr(65536), sc(65536)
integer*8 bigd, d2, dx, dy
read(5,*) nrow, ncol
for (i = 1; i <= nrow; i = i + 1) {
  read(5,*) (g(i,j), j = 1, ncol)
}
ndies = 0
bigd = 0
for (i = 1; i <= nrow; i = i + 1) {
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) >= 1) {
      ndies = ndies + 1
      dx = 2*(i-1) - (nrow-1)
      dy = 2*(j-1) - (ncol-1)
      d2 = dx*dx + dy*dy
      if (d2 > bigd) bigd = d2
    }
  }
}
nring = 0
for (i = 1; i <= nrow; i = i + 1) {
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) == 2) {
      dx = 2*(i-1) - (nrow-1)
      dy = 2*(j-1) - (ncol-1)
      d2 = dx*dx + dy*dy
      if (2500*bigd <= 10000*d2) nring = nring + 1
    }
  }
}
ncl = 0
lmax = 0
for (i = 1; i <= nrow; i = i + 1) {
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) == 2) {
      if (vis(i,j) == 0) {
        vis(i,j) = 1
        top = 1
        sr(1) = i
        sc(1) = j
        sz = 0
        while (top > 0) {
          cr = sr(top)
          cc = sc(top)
          top = top - 1
          sz = sz + 1
          for (dr = -1; dr <= 1; dr = dr + 1) {
            for (dc = -1; dc <= 1; dc = dc + 1) {
              nr = cr + dr
              nc = cc + dc
              if (nr >= 1) {
                if (nr <= nrow) {
                  if (nc >= 1) {
                    if (nc <= ncol) {
                      if (g(nr,nc) == 2) {
                        if (vis(nr,nc) == 0) {
                          vis(nr,nc) = 1
                          top = top + 1
                          sr(top) = nr
                          sc(top) = nc
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        if (sz >= 5) ncl = ncl + 1
        if (sz > lmax) lmax = sz
      }
    }
  }
}
write(6,*) nring, ndies, ncl, lmax
end

