integer nrow, ncol, r, c, g(256,256), vis(256,256)
integer stkr(65536), stkc(65536), sp, pr, pc, nr, nc, csz, ox, oy
integer ring, fails, clusters
integer*8 d2, dmax, dr, dc
read(5,*) nrow, ncol
do r = 1, nrow {
  read(5,*) (g(r,c), c = 1, ncol)
}
dmax = 0
fails = 0
do r = 1, nrow {
  do c = 1, ncol {
    vis(r,c) = 0
    if (g(r,c) != 0) {
      dr = 2*r - nrow - 1
      dc = 2*c - ncol - 1
      d2 = dr*dr + dc*dc
      if (d2 > dmax) dmax = d2
    }
    if (g(r,c) == 2) fails = fails + 1
  }
}
ring = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) == 2) {
      dr = 2*r - nrow - 1
      dc = 2*c - ncol - 1
      d2 = dr*dr + dc*dc
      if (0 <= 10000*d2 & 10000*d2 < 900*dmax) ring = ring + 1
    }
  }
}
clusters = 0
do r = 1, nrow {
  do c = 1, ncol {
    if (g(r,c) == 2 & vis(r,c) == 0) {
      vis(r,c) = 1
      sp = 1
      stkr(1) = r
      stkc(1) = c
      csz = 0
      while (sp > 0) {
        pr = stkr(sp)
        pc = stkc(sp)
        sp = sp - 1
        csz = csz + 1
        do ox = -1, 1 {
          do oy = -1, 1 {
