for (r = 1; r <= rows; r = r + 1)
  read(5,*) (g(r,j), j = 1, cols)
dmax2 = 0
for (r = 1; r <= rows; r = r + 1) {
  for (c = 1; c <= cols; c = c + 1) {
    if (g(r,c) != 0) {
      a = 2*r - rows - 1
      b = 2*c - cols - 1
      d2 = a*a + b*b
      if (d2 > dmax2) dmax2 = d2
    }
  }
}
ringf = 0
edgef = 0
dies = 0
fails = 0
for (r = 1; r <= rows; r = r + 1) {
  for (c = 1; c <= cols; c = c + 1) {
    if (g(r,c) != 0) {
      dies = dies + 1
      if (g(r,c) == 2) {
        fails = fails + 1
        a = 2*r - rows - 1
        b = 2*c - cols - 1
        d2 = a*a + b*b
        # 70^2*D2 <= 100^2*d2  <=>  49*D2 <= 100*d2
        if (49*dmax2 <= 100*d2) ringf = ringf + 1
        flag = 0
        for (dr = -1; dr <= 1; dr = dr + 1) {
          for (dc = -1; dc <= 1; dc = dc + 1) {
            if (dr != 0 | dc != 0) {
              nr = r + dr
              nc = c + dc
              if (nr < 1 | nr > rows | nc < 1 | nc > cols) {
                flag = 1
              } else if (g(nr,nc) == 0) {
                flag = 1
              }
            }
          }
        }
        if (flag == 1) edgef = edgef + 1
      }
    }
  }
}
if (dies > 0)
  ypm = 1000*(dies - fails)/dies
else
  ypm = 0
write(6,*) ringf, edgef, ypm
end

# Wafer map measurement: ring fails, edge fails, yield per mille
integer nrow, ncol, r, c, dr, dc, nr, nc, ii, jj
integer g(256,256)
integer*8 d2, d2max, lhs, rhs
integer ringf, edgef, dies, fails, yld, edge

ringf = 0
edgef = 0
dies = 0
fails = 0
d2max = 0

read(5,*) nrow, ncol
for (r = 1; r <= nrow; r = r + 1) {
  read(5,*) (g(r,c), c = 1, ncol)
}

# First pass: count dies and find the largest squared distance D2
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) != 0) {
      dies = dies + 1
      if (g(r,c) == 2) fails = fails + 1
      ii = 2*r - nrow - 1
      jj = 2*c - ncol - 1
      d2 = ii*ii + jj*jj
      if (d2 > d2max) d2max = d2
    }
  }
}

# Second pass: ring fails and edge fails for failing dies
for (r = 1; r <= nrow; r = r + 1) {
  for (c = 1; c <= ncol; c = c + 1) {
    if (g(r,c) == 2) {
      ii = 2*r - nrow - 1
      jj = 2*c - ncol - 1
      d2 = ii*ii + jj*jj
      lhs = 4900 * d2max
      rhs = 10000 * d2
      if (lhs <= rhs) ringf = ringf + 1

      edge = 0
      for (dr = -1; dr <= 1; dr = dr + 1) {
        for (dc = -1; dc <= 1; dc = dc + 1) {
          if (dr == 0 & dc == 0) next
          nr = r + dr
          nc = c + dc
          if (nr < 1 | nr > nrow | nc < 1 | nc > ncol) {
            edge = 1
          } else {
            if (g(nr,nc) == 0) edge = 1
          }
        }
      }
      if (edge == 1) edgef = edgef + 1
    }
  }
}

if (dies > 0) {
  yld = (1000 * (dies - fails)) / dies
} else {
  yld = 0
}

write(6,*) ringf, edgef, yld
end

