do r = 1, n {
  do c = 1, m {
    if (g(r,c) != 0) {
      x = 2*r - (n-1)
      y = 2*c - (m-1)
      d2 = x*x + y*y
      if (d2 > dmax) dmax = d2
    }
  }
}

