integer NR, NC, r, c, j, sp, cr, cc, nr2, nc2, dr, dc, sz
integer ta, tb, clusters, fails, ringf
integer g(256,256), vis(256,256), sr(65536), sc(65536)
integer*8 dd2, bigd2

read(5,*) NR, NC
for (r = 1; r <= NR; r = r + 1) {
  read(5,*) (g(r,j), j = 1, NC)
}

clusters = 0
fails = 0
for (r = 1; r <= NR; r = r + 1) {
  for (c = 1; c <= NC; c = c + 1) {
    vis(r,c) = 0
    if (g(r,c) == 2) fails = fails + 1
  }
}

# 8-connected clusters of failing dies, counted if size >= 3
for (r = 1; r <= NR; r = r + 1) {
  for (c = 1; c <= NC; c = c + 1) {
    if (g(r,c) == 2 & vis(r,c) == 0) {
      vis(r,c) = 1
      sp = 1
      sr(sp) = r
      sc(sp) = c
      sz = 0
      while (sp > 0) {
        cr = sr(sp)
        cc = sc(sp)
        sp = sp - 1
        sz = sz + 1
        for (dr = -1; dr <= 1; dr = dr + 1)
          for (dc = -1; dc <= 1; dc = dc + 1) {
            nr2 = cr + dr
            nc2 = cc + dc
            if (nr2 < 1 | nr2 > NR | nc2 < 1 | nc2 > NC) next
            if (g(nr2,nc2) != 2 | vis(nr2,nc2) != 0) next
            vis(nr2,nc2) = 1
            sp = sp + 1
            sr(sp) = nr2
            sc(sp) = nc2
          }
      }
      if (sz >= 3) clusters = clusters + 1
    }
  }
}

# largest squared distance over all dies
bigd2 = 0
for (r = 1; r <= NR; r = r + 1) {
  for (c = 1; c <= NC; c = c + 1) {
    if (g(r,c) != 0) {
      ta = 2*(r-1) - (NR-1)
      tb = 2*(c-1) - (NC-1)
      dd2 = ta*ta + tb*tb
      if (dd2 > bigd2) bigd2 = dd2
    }
  }
}

# failing dies in ring 0%..30%: 10000*d2 < 900*D2
ringf = 0
for (r = 1; r <= NR; r = r + 1) {
  for (c = 1; c <= NC; c = c + 1) {
    if (g(r,c) == 2) {
      ta = 2*(r-1) - (NR-1)
      tb = 2*(c-1) - (NC-1)
      dd2 = ta*ta + tb*tb
      if (10000*dd2 < 900*bigd2) ringf = ringf + 1
    }
  }
}

write(6,*) clusters, fails, ringf
end

