subroutine flood(g, vis, nr, nc, r0, c0, conn, sr, sc, sz)
integer g(256,256), vis(256,256), nr, nc, r0, c0, conn, sr(65536), sc(65536), sz
integer sp, r, c, dr, dc, nrr, ncc
vis(r0,c0) = 1
sp = 1
sr(1) = r0
sc(1) = c0
sz = 0
while (sp > 0) {
  r = sr(sp)
  c = sc(sp)
  sp = sp - 1
  sz = sz + 1
  for (dr = -1; dr <= 1; dr = dr + 1) {
    for (dc = -1; dc <= 1; dc = dc + 1) {
      if (dr == 0 & dc == 0) next
      if (conn == 4 & dr != 0 & dc != 0) next
      nrr = r + dr
      ncc = c + dc
      if (nrr >= 1 & nrr <= nr & ncc >= 1 & ncc <= nc) {
        if (g(nrr,ncc) == 2 & vis(nrr,ncc) == 0) {
          vis(nrr,ncc) = 1
          sp = sp + 1
          sr(sp) = nrr
          sc(sp) = ncc
        }
      }
    }
  }
}
end

integer g(256,256), vis(256,256), sr(65536), sc(65536)
integer nr, nc, r, c, j, ndies, d2, maxd2, t, u, nclus, nedge, nring, big, sz, edge

read(5,*) nr, nc
do r = 1, nr {
  read(5,*) (g(r,j), j = 1, nc)
}

ndies = 0
maxd2 = -1
do r = 1, nr {
  do c = 1, nc {
    if (g(r,c) != 0) {
      ndies = ndies + 1
      t = 2*r - nr - 1
      u = 2*c - nc - 1
      d2 = t*t + u*u
      if (d2 > maxd2) maxd2 = d2
    }
  }
}

nedge = 0
nring = 0
do r = 1, nr {
  do c = 1, nc {
    if (g(r,c) == 2) {
      edge = 0
      if (r == 1 | r == nr | c == 1 | c == nc) edge = 1
      if (edge == 0) {
        if (g(r-1,c) == 0 | g(r+1,c) == 0 | g(r,c-1) == 0 | g(r,c+1) == 0) edge = 1
      }
      if (edge == 1) nedge = nedge + 1
      t = 2*r - nr - 1
      u = 2*c - nc - 1
      d2 = t*t + u*u
      if (100*d2 < 9*maxd2) nring = nring + 1
    }
  }
}

do r = 1, nr {
  do j = 1, nc {
    vis(r,j) = 0
  }
}
nclus = 0
do r = 1, nr {
  do c = 1, nc {
    if (g(r,c) == 2 & vis(r,c) == 0) {
      call flood(g, vis, nr, nc, r, c, 4, sr, sc, sz)
      if (sz >= 2) nclus = nclus + 1
    }
  }
}

do r = 1, nr {
  do j = 1, nc {
    vis(r,j) = 0
  }
}
big = 0
do r = 1, nr {
  do c = 1, nc {
    if (g(r,c) == 2 & vis(r,c) == 0) {
      call flood(g, vis, nr, nc, r, c, 8, sr, sc, sz)
      if (sz > big) big = sz
    }
  }
}

write(6,*) nclus, nedge, ndies, nring, big
end

