integer g(258,258), vis(258,258), sr(66564), sc(66564)
integer R, C, i, j, sz, nclus, efail, ndies, nring, lmax
integer dr, dc, nb
integer*8 d2, d2max

read(5,*) R, C
do i = 1, R {
  read(5,*) (g(i+1,j+1), j = 1, C)
}

# phase 1: clusters of failing dies, 4-connectivity, size >= 2
do i = 1, R+2 {
  do j = 1, C+2 {
    vis(i,j) = 0
  }
}
nclus = 0
do i = 2, R+1 {
  do j = 2, C+1 {
    if (g(i,j) == 2 & vis(i,j) == 0) {
      call fill(g, vis, sr, sc, i, j, 0, sz)
      if (sz >= 2) nclus = nclus + 1
    }
  }
}

# phase 2 and 3: edge fails and dies, plus largest d2 over dies
efail = 0
ndies = 0
d2max = 0
do i = 2, R+1 {
  do j = 2, C+1 {
    if (g(i,j) == 1 | g(i,j) == 2) {
      ndies = ndies + 1
      dr = 2*(i-1) - (R+1)
      dc = 2*(j-1) - (C+1)
      d2 = dr*dr + dc*dc
      if (d2 > d2max) d2max = d2
    }
    if (g(i,j) == 2) {
      nb = 0
      if (g(i-1,j) == 0) nb = 1
      if (g(i+1,j) == 0) nb = 1
      if (g(i,j-1) == 0) nb = 1
      if (g(i,j+1) == 0) nb = 1
      if (nb == 1) efail = efail + 1
    }
  }
}

# phase 4: ring fails, 0% to 30% band
nring = 0
do i = 2, R+1 {
  do j = 2, C+1 {
    if (g(i,j) == 2) {
      dr = 2*(i-1) - (R+1)
      dc = 2*(j-1) - (C+1)
      d2 = dr*dr + dc*dc
      if (10000*d2 < 900*d2max) nring = nring + 1
    }
  }
}

# phase 5: largest cluster of failing dies, 8-connectivity
do i = 1, R+2 {
  do j = 1, C+2 {
    vis(i,j) = 0
  }
}
lmax = 0
do i = 2, R+1 {
  do j = 2, C+1 {
    if (g(i,j) == 2 & vis(i,j) == 0) {
      call fill(g, vis, sr, sc, i, j, 1, sz)
      if (sz > lmax) lmax = sz
    }
  }
}

write(6,*) nclus, efail, ndies, nring, lmax
end

