subroutine fill(r0, c0, conn, sz)
integer r0, c0, conn, sz, r, c, dr, dc, nr, nc
integer nrow, ncol, g(256,256), vis(256,256), sr(65536), sc(65536), sp
common /wafer/ nrow, ncol, g, vis, sr, sc, sp

sp = 1
sr(1) = r0
sc(1) = c0
vis(r0,c0) = 1
sz = 0
while (sp > 0) {
  r = sr(sp)
  c = sc(sp)
  sp = sp - 1
  sz = sz + 1
  for (dr = -1; dr <= 1; dr = dr + 1)
    for (dc = -1; dc <= 1; dc = dc + 1) {
      if (dr == 0 & dc == 0) next
      if (conn == 4 & dr != 0 & dc != 0) next
      nr = r + dr
      nc = c + dc
      if (nr < 1 | nr > nrow) next
      if (nc < 1 | nc > ncol) next
      if (g(nr,nc) != 2) next
      if (vis(nr,nc) != 0) next
      vis(nr,nc) = 1
      sp = sp + 1
      sr(sp) = nr
      sc(sp) = nc
    }
}
return
end

integer function cellv(r, c)
