subroutine flood(g, nr, nc, seen, stk, r0, c0, conn, sz)
integer nr, nc, r0, c0, conn, sz
integer g(nr,nc), seen(nr,nc), stk(65536)
integer top, cur, r, c, k, nd, rr, cc
integer dr(8), dc(8)
data dr /-1,1,0,0,-1,-1,1,1/
data dc /0,0,-1,1,-1,1,-1,1/

nd = 8
if (conn == 4) nd = 4
sz = 0
top = 1
stk(1) = r0*512 + c0
seen(r0,c0) = 1
while (top > 0) {
  cur = stk(top)
  top = top - 1
  r = cur/512
  c = mod(cur,512)
  sz = sz + 1
  for (k = 1; k <= nd; k = k + 1) {
    rr = r + dr(k)
    cc = c + dc(k)
    if (rr >= 1 & rr <= nr & cc >= 1 & cc <= nc) {
      if (g(rr,cc) == 2 & seen(rr,cc) == 0) {
        seen(rr,cc) = 1
        top = top + 1
        stk(top) = rr*512 + cc
      }
    }
  }
}
end

