  for (j = 1; j <= ncol; j = j + 1) {
    vis(i,j) = 0
    if (g(i,j) != 0) {
      dies = dies + 1
      if (g(i,j) == 2) fails = fails + 1
      dr = 2*i - nrow - 1
      dc = 2*j - ncol - 1
      d2 = dr*dr + dc*dc
      if (d2 > dmax) dmax = d2
    }
  }
}

yld = 0
if (dies > 0) yld = 1000 * (dies - fails) / dies

# ring from lo=0 to hi=100 percent
ring = 0
for (i = 1; i <= nrow; i = i + 1) {
  for (j = 1; j <= ncol; j = j + 1) {
    if (g(i,j) == 2) {
      dr = 2*i - nrow - 1
      dc = 2*j - ncol - 1
      d2 = dr*dr + dc*dc
      if (0 <= 10000 * d2) ring = ring + 1
    }
  }
}

