          else if (k == 2) { nr = cr + 1; nc = cc }
          else if (k == 3) { nr = cr; nc = cc - 1 }
          else { nr = cr; nc = cc + 1 }
          if (nr >= 1 & nr <= nrow & nc >= 1 & nc <= ncol) {
