ring = 0
edge = 0
fails = 0
for (i = 1; i <= R; i = i + 1) {
  for (j = 1; j <= C; j = j + 1) {
    if (g(i,j) == 2) {
      fails = fails + 1

      # ring test: 30^2*D2 <= 10000*d2 < 70^2*D2
      r2 = 2*(i-1) - (R-1)
      c2 = 2*(j-1) - (C-1)
      d2 = r2*r2 + c2*c2
      a = 900*D2
      b = 10000*d2
      if (a <= b & b < 4900*D2) ring = ring + 1

      # edge test: a 4-neighbour is 0 or off the map
      ex = 0
