      g(i,j) = 1
      sp = 1
      stk(1) = i*512 + j
      sz = 0
      while (sp > 0) {
        cc = stk(sp)
        sp = sp - 1
        sz = sz + 1
        ci = cc / 512
        cj = mod(cc, 512)
        for (di = -1; di <= 1; di = di + 1) {
          for (dj = -1; dj <= 1; dj = dj + 1) {
            ni = ci + di
            nj = cj + dj
